<template>
 <section class="quote-presentation-form">
  <span class="presentation-label" id="quote-presentation-label">PRESENTACIÓN DE LA PROFORMA</span>
  <div class="presentation-choices" role="group" aria-labelledby="quote-presentation-label">
   <button type="button" class="presentation-choice" :class="{'is-selected':(value.tipo || 'productos')==='productos' &amp;&amp; value.formatoProducto!=='destacado'}" :aria-pressed="(value.tipo || 'productos')==='productos' &amp;&amp; value.formatoProducto!=='destacado'" :disabled="disabled" @click="choosePresentation('productos','catalogo')"><span class="presentation-number">01</span><strong>Productos comerciales</strong><small>Catálogo con imagen y descripción</small></button>
   <button type="button" class="presentation-choice" :class="{'is-selected':value.tipo==='sistemas'}" :aria-pressed="value.tipo==='sistemas'" :disabled="disabled" @click="choosePresentation('sistemas','catalogo')"><span class="presentation-number">02</span><strong>Sistemas</strong><small>Propuesta profesional y módulos</small></button>
   <button type="button" class="presentation-choice" :class="{'is-selected':value.tipo!=='sistemas' &amp;&amp; value.formatoProducto==='destacado'}" :aria-pressed="value.tipo!=='sistemas' &amp;&amp; value.formatoProducto==='destacado'" :disabled="disabled" @click="choosePresentation('productos','destacado')"><span class="presentation-number">03</span><strong>Producto destacado</strong><small>Imagen grande + características al costado</small></button>
  </div>
  <p v-if="value.tipo!=='sistemas' &amp;&amp; value.formatoProducto==='destacado'" class="presentation-featured-hint">Presentación con la foto del producto en grande, características a la derecha e importes en una franja inferior.</p>
  <template v-if="value.tipo==='sistemas'">
   <section class="proposal-template-card">
    <strong>Configuración de este producto</strong>
    <label v-if="templateProducts.length">Producto base<select v-model="templateId" :disabled="busy || savingTemplate" @change="loadTemplate"><option v-for="p in templateProducts" :key="p.IdProducto" :value="Number(p.IdProducto)">{{p.Producto}}</option></select></label>
    <p>{{templateLoaded?'Plantilla guardada cargada. Se reutiliza para este producto; personaliza solo las excepciones del cliente.':'Configura una vez los módulos y los textos; guarda la plantilla para reutilizarla con este producto.'}}</p>
    <button type="button" @click="saveTemplate" :disabled="disabled || busy || savingTemplate || !templateId">{{savingTemplate?'Guardando…':'Guardar configuración para este producto'}}</button>
    <p v-if="templateMessage" role="status">{{templateMessage}}</p>
   </section>
   <section class="proposal-assistant">
    <header><div><span>ALI · ASISTENTE DE PROPUESTAS</span><strong>Prepara una propuesta para cada negocio</strong></div><button type="button" @click="assistantOpen=!assistantOpen">{{assistantOpen?'Ocultar asistente':'Abrir asistente IA'}}</button></header>
    <div v-show="assistantOpen">
     <div class="proposal-guide"><b>1. Define el negocio</b><span>2. Revisa lo que incluye el producto</span><span>3. Redacta y aplica la propuesta</span></div>
     <div class="proposal-ai-grid"><label>Rubro del negocio<input v-model="rubro" list="proposal-business-types" maxlength="120" placeholder="Busca un rubro o escribe cualquier actividad" :disabled="busy || disabled"><datalist id="proposal-business-types"><option v-for="item in rubros" :key="item" :value="item"/></datalist></label><label>Estilo de presentación<select v-model="style" :disabled="busy || disabled"><option value="corporativo">Corporativo y elegante</option><option value="comercial">Comercial y orientado al cliente</option><option value="tecnico">Técnico y detallado</option></select></label></div>
     <label><span class="proposal-field-heading">¿Qué necesita el cliente?<button type="button" class="proposal-dictate" @click="dictate('needs')" :disabled="!voiceSupported || busy || disabled">{{dictating==='needs'?'■ Detener':'🎙 Dictar necesidades'}}</button></span><textarea v-model="needs" rows="3" maxlength="4000" :disabled="busy || disabled" placeholder="Describe el negocio, sus problemas, locales, usuarios y lo que deseas ofrecer."/></label>
     <details class="proposal-modules"><summary>Módulos incluidos en este producto <span>{{selected.length}} seleccionados</span></summary><input v-model="moduleSearch" placeholder="Buscar módulo por nombre" aria-label="Buscar módulo por nombre" :disabled="busy || disabled"><div class="proposal-module-actions"><button type="button" @click="generate(true)" :disabled="busy || disabled || loadingCatalog">Sugerir módulos con IA</button><button type="button" @click="suggestModules" :disabled="busy || disabled || !modules.length">Sugerir según rubro</button><button type="button" @click="selected=modules.map(m=>m.id)" :disabled="busy || disabled">Todos</button><button type="button" @click="selected=[]" :disabled="busy || disabled">Limpiar</button></div><div class="proposal-module-list"><label v-for="m in filteredModules" :key="m.id"><input type="checkbox" v-model="selected" :value="m.id" :disabled="busy || disabled"><span>{{m.name}}<small>{{m.detail}}</small></span></label></div><p v-if="loadingCatalog">Cargando módulos…</p><p v-else-if="!modules.length">No se pudo cargar el catálogo de módulos. {{catalogError}}</p></details>
     <details class="proposal-services" open>
      <summary>Soporte y servicios incluidos <span>{{supportSelected.length}} seleccionados</span></summary>
      <p>Marca lo que entregarás al cliente. Las selecciones se incorporan al borrador y puedes guardarlas en la plantilla del producto.</p>
      <div class="proposal-plan-intro"><span>UN SOLO PLAN · SERVICIOS INTEGRADOS</span><strong>Facturación, infraestructura y acompañamiento</strong><p>Presenta al cliente una solución continua: el primer año del plan va incluido en la licencia y se renueva con un único valor anual.</p><button type="button" @click="supportSelected=supportOptions.filter(s=>s.annualPlan).map(s=>s.id).concat('annual_billing')" :disabled="busy || disabled">Seleccionar plan anual integral</button></div>
      <div class="proposal-module-actions"><button type="button" @click="supportSelected=supportOptions.filter(s=>s.recommended).map(s=>s.id)" :disabled="busy || disabled">Seleccionar recomendados</button><button type="button" @click="generate('support')" :disabled="busy || disabled || loadingCatalog">Recomendar servicios con IA</button><button type="button" @click="supportSelected=[]" :disabled="busy || disabled">Limpiar servicios</button></div>
      <div class="proposal-service-list"><label v-for="service in supportOptions" :key="service.id" :class="{'is-selected':supportSelected.includes(service.id)}"><input type="checkbox" v-model="supportSelected" :value="service.id" :disabled="busy || disabled"><span><b>{{service.name}}</b><small>{{service.description}}</small><em v-if="service.recommended">Recomendado</em></span></label></div>
      <label v-if="supportSelected.includes('annual_billing')" class="proposal-annual-fee">Valor anual del plan integral (S/)<select v-model="annualFee" :disabled="busy || disabled"><option value="">Seleccionar valor anual</option><option v-for="amount in [1000,900,800,700,600,500]" :key="amount" :value="amount">S/ {{amount.toFixed(2)}} al año</option></select><small>Un solo valor para los servicios seleccionados del plan. Primer año incluido en la licencia; renovación desde el segundo año. No modifica el total de la proforma.</small></label>
      <section v-if="supportRecommendation.length" class="proposal-ai-note"><strong>Servicios sugeridos para revisar</strong><p>{{supportOptions.filter(s=>supportRecommendation.includes(s.id)).map(s=>s.name).join(' · ')}}</p><p>{{supportNotes.join(' ')}}</p><button type="button" @click="supportSelected=supportRecommendation.slice();supportRecommendation=[]">Usar estos servicios recomendados</button></section>
      <button type="button" class="proposal-apply-services" @click="applyServices" :disabled="busy || disabled">Aplicar servicios seleccionados a los textos</button>
      <p>24/7 indica el horario de atención. La validación SUNAT corresponde a los comprobantes electrónicos emitidos; no incluye declaraciones tributarias.</p>
     </details>
     <section v-if="recommendation.length" class="proposal-ai-note"><strong>Sugerencia para revisar</strong><p>{{modules.filter(m=>recommendation.includes(m.id)).map(m=>m.name).join(' · ')}}</p><p>{{recommendationNotes.join(' ')}}</p><button type="button" @click="selected=recommendation.slice();recommendation=[]">Usar esta selección de módulos</button></section><p class="proposal-ai-note">Selecciona únicamente lo incluido en esta oferta. Los demás módulos del ERP no se ofrecen automáticamente.</p><p v-if="settings &amp;&amp; !settings.configured" class="proposal-ai-note">Falta la clave de IA. Puedes preparar una base guiada y seguir editando. <a href="/views/V_VentaForm.php" target="_blank" rel="noopener">Abrir ventas para Configurar ALI</a></p>
     <div class="proposal-ai-actions"><button type="button" @click="guidedDraft" :disabled="busy || disabled || loadingCatalog">Preparar base guiada</button><button type="button" class="proposal-generate" @click="generate(false)" :disabled="disabled || busy || loadingCatalog">{{busy?'Redactando propuesta…':'✦ Mejorar presentación con IA'}}</button><button v-if="busy" type="button" @click="cancelRequest">Cancelar espera</button><small>Usa los módulos seleccionados y los productos de esta proforma. No guarda ni envía automáticamente.</small></div>
     <p v-if="error" class="proposal-ai-error" role="alert">{{error}}</p><p v-if="voiceError" class="proposal-ai-error" role="alert">{{voiceError}}</p><p v-if="dictating" class="proposal-ai-note" role="status">Escuchando… habla con claridad. {{interim}}</p><p v-if="success" class="proposal-ai-note" role="status">{{success}}</p>
     <section v-if="draft" class="proposal-ai-preview"><strong>Borrador para revisar</strong><label>Alcance propuesto<textarea v-model="draft.alcance" rows="4" maxlength="12000"/></label><label>Entregables propuestos<textarea v-model="draft.entregables" rows="3" maxlength="12000"/></label><label>Condiciones propuestas<textarea v-model="draft.condiciones" rows="3" maxlength="12000"/></label><div v-if="draft.pendientes &amp;&amp; draft.pendientes.length"><strong>Datos por confirmar con el cliente</strong><ul><li v-for="(item,i) in draft.pendientes" :key="i">{{item}}</li></ul></div><label>Cómo aplicar<select v-model="applyMode"><option value="empty">Completar solo campos vacíos</option><option value="replace">Reemplazar textos con este borrador</option></select></label><label class="proposal-reviewed"><input type="checkbox" v-model="reviewed"> Revisé el alcance y las condiciones ofrecidas.</label><button type="button" @click="applyDraft" :disabled="!reviewed || busy || disabled">Aplicar borrador a la proforma</button></section>
    </div>
   </section>
   <p>Estos textos aparecerán en la propuesta enviada al cliente. Puedes editarlos antes de guardarla.</p>
   <label><span class="proposal-field-heading">Alcance del sistema *<button type="button" class="proposal-dictate" @click="dictate('alcance')" :disabled="!voiceSupported || busy || disabled">{{dictating==='alcance'?'■ Detener':'🎙 Dictar'}}</button></span><textarea :value="value.alcance || ''" @input="set('alcance',$event.target.value)" rows="4" maxlength="12000" :disabled="disabled" placeholder="Objetivo, módulos incluidos, usuarios, locales y límites de la solución."/></label>
   <label><span class="proposal-field-heading">Implementación y entregables<button type="button" class="proposal-dictate" @click="dictate('entregables')" :disabled="!voiceSupported || busy || disabled">{{dictating==='entregables'?'■ Detener':'🎙 Dictar'}}</button></span><textarea :value="value.entregables || ''" @input="set('entregables',$event.target.value)" rows="3" maxlength="12000" :disabled="disabled" placeholder="Instalación, configuración, capacitación, documentación y plazo acordado."/></label>
   <label><span class="proposal-field-heading">Condiciones y exclusiones<button type="button" class="proposal-dictate" @click="dictate('condiciones')" :disabled="!voiceSupported || busy || disabled">{{dictating==='condiciones'?'■ Detener':'🎙 Dictar'}}</button></span><textarea :value="value.condiciones || ''" @input="set('condiciones',$event.target.value)" rows="3" maxlength="12000" :disabled="disabled" placeholder="Licencia, soporte, renovaciones, forma de pago y servicios no incluidos."/></label>
  </template>
 </section>
</template>
<script>
import { proposalServices, defaultProposalServices, applyProposalServices } from '../utils/proformaServices';
export default {
 props:{value:{type:Object,default:()=>({tipo:'productos'})},disabled:Boolean,active:{type:Boolean,default:true},products:{type:Array,default:()=>[]}},
 data(){return {annualFee:'',supportOptions:proposalServices,supportSelected:defaultProposalServices(),supportRecommendation:[],supportNotes:[],assistantOpen:true,rubro:'',style:'corporativo',needs:'',moduleSearch:'',modules:[],selected:[],settings:null,loadingCatalog:false,catalogError:'',busy:false,error:'',success:'',draft:null,reviewed:false,applyMode:'empty',dictating:'',voiceError:'',interim:'',recommendation:[],recommendationNotes:[],templateId:0,templateLoaded:false,savingTemplate:false,templateMessage:'',voiceSupported:!!(window.SpeechRecognition || window.webkitSpeechRecognition),rubros:['Market / bodega','Supermercado','Minimarket','Abarrotes mayoristas','Ferretería','Materiales de construcción','Farmacia / botica','Distribuidora farmacéutica','Restaurante','Pollería','Cevichería','Cafetería','Panadería / pastelería','Bar / discoteca','Hotel / hospedaje','Turismo / agencia de viajes','Comercio de tecnología','Computadoras y accesorios','Electrodomésticos','Seguridad electrónica','Telefonía / celulares','Ropa / boutique','Calzado','Textiles / confecciones','Joyería','Librería / papelería','Imprenta / publicidad','Repuestos automotrices','Taller mecánico','Lubricentro','Transporte / logística','Distribuidora','Importación / exportación','Agroindustria','Agroveterinaria','Veterinaria / mascotas','Clínica / consultorio','Odontología','Laboratorio','Óptica','Belleza / peluquería','Spa / estética','Gimnasio','Educación / academia','Colegio / instituto','Servicios profesionales','Consultoría','Contabilidad / estudio contable','Ingeniería / arquitectura','Constructora','Inmobiliaria','Manufactura / producción','Muebles / carpintería','Metal mecánica','Alquiler de equipos','Lavandería','Estación de servicios','Comercio electrónico','Software / sistemas ERP','Servicios empresariales','Negocio a medida']};},
 computed:{templateProducts(){return this.products.filter(p=>Number(p.IdProducto)>0);},productKey(){return this.templateProducts.map(p=>p.IdProducto).join(',');},filteredModules(){const term=this.moduleSearch.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return this.modules.filter(m=>(m.name+' '+m.detail).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(term));},canGenerate(){return this.settings && this.settings.configured && this.selected.length;}},
 watch:{productKey(){this.templateId=0;this.templateLoaded=false;this.supportSelected=defaultProposalServices();if(this.active && this.value.tipo==='sistemas')this.loadTemplate();},'value.tipo':{immediate:true,handler(type){if(type==='sistemas' && this.active){this.loadCatalog();}else{this.stopVoice();this.cancelRequest();}}},active(value){if(!value){this._templateSequence=(this._templateSequence||0)+1;this.stopVoice();this.cancelRequest();}else if(this.value.tipo==='sistemas'){this.loadCatalog();this.loadTemplate();}},disabled(value){if(value){this.stopVoice();this.cancelRequest();}}},
 beforeDestroy(){this.stopVoice();this.cancelRequest();},
 methods:{choosePresentation(tipo,formatoProducto){this.$emit('input',Object.assign({},this.value,{tipo,formatoProducto}));},servicesReady(){if(this.supportSelected.includes('annual_billing')&&!([1000,900,800,700,600,500].includes(Number(this.annualFee)))){this.error='Selecciona el valor anual de facturación electrónica antes de continuar.';return false;}return true;},set(key,value){this.$emit('input',Object.assign({},this.value,{[key]:value}));},
 async call(body,signal){const response=await fetch('/api/index.php/ali/producto',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':this.settings?this.settings.csrf:''},body:JSON.stringify(body),signal});let data;try{data=await response.json();}catch(e){throw Error('El servidor no devolvió una respuesta válida. Tus textos se conservan.');}if(!response.ok)throw Error(data.error || 'No se pudo completar la consulta.');return data;},
 async loadCatalog(){if(this.loadingCatalog)return;if(this.modules.length){this.loadTemplate();return;}this.loadingCatalog=true;this.catalogError='';try{const r=await fetch('/api/index.php/ali/config',{credentials:'same-origin'});const config=await r.json();if(!r.ok)throw Error(config.error || 'Revisa tu sesión.');this.settings=config;const data=await this.call({mode:'proposal_catalog'});this.modules=data.modules || [];if(!this.selected.length)this.suggestModules();await this.loadTemplate();}catch(e){this.catalogError=e.message;}finally{this.loadingCatalog=false;}},
 suggestModules(){const product=this.templateProducts.map(p=>p.Producto+' '+(p.ProductoDesc||'')).join(' ').toLowerCase();if(/facturaci[oó]n/.test(product) && !/market|erp completo/.test(product)){this.selected=this.modules.filter(m=>['sales','clients'].includes(m.id)||/facturaci[oó]n electr[oó]nica/i.test(m.name)).map(m=>m.id);return;}const ids=['sales','catalog','inventory','purchases','cash','reports','clients','security'];const business=this.rubro.toLowerCase();if(/hotel|hosped/.test(business))ids.push('hotel');if(/servicio|medida/.test(business))ids.push('projects','crm');if(/distribu/.test(business))ids.push('crm','store');this.selected=this.modules.filter(m=>ids.includes(m.id)).map(m=>m.id);},
 async generate(recommend=false){if(this.busy || this.disabled)return;if(!this.servicesReady())return;this.error='';if(!this.rubro.trim())this.rubro='Servicios empresariales';try{const response=await fetch('/api/index.php/ali/config',{credentials:'same-origin'});this.settings=await response.json();if(!response.ok)throw Error(this.settings.error||'Revisa tu sesión.');}catch(e){this.error=e.message;return;}if(!this.settings.configured || (!recommend && !this.selected.length)){this.error=!this.selected.length?'Selecciona los módulos incluidos en el producto.':'Falta configurar la clave de IA en ALI. Puedes usar Preparar base guiada mientras tanto.';return;}this.stopVoice();this.error='';this.success='';this.reviewed=false;this.busy=true;const seq=(this._sequence || 0)+1;this._sequence=seq;this._abort=new AbortController();const timer=setTimeout(()=>this._abort && this._abort.abort(),65000);try{const data=await this.call({mode:'proposal_draft',objetivo:recommend==='support'?'soportes':recommend?'recomendar':'redactar',rubro:this.rubro,estilo:this.style,necesidades:this.needs,modulos:recommend===true?this.modules.map(m=>m.id):this.selected,soportes:this.supportSelected,anualidad_facturacion:this.supportSelected.includes('annual_billing')?Number(this.annualFee):null,actual:{alcance:this.value.alcance||'',entregables:this.value.entregables||'',condiciones:this.value.condiciones||''},productos:[...new Set(this.products.map(p=>Number(p.IdProducto)).filter(n=>n>0))].slice(0,50)},this._abort.signal);if(seq!==this._sequence || !this.active)return;if(!data.draft || !['alcance','entregables','condiciones'].every(k=>typeof data.draft[k]==='string'))throw Error('El borrador llegó incompleto. Intenta nuevamente.');if(recommend==='support'){this.supportRecommendation=(data.draft.soportes_recomendados||[]).filter(id=>this.supportOptions.some(s=>s.id===id));this.supportNotes=data.draft.pendientes||[];this.success=this.supportRecommendation.length?'Revisa los servicios sugeridos y pulsa Usar estos servicios recomendados.':'La IA no sugirió servicios adicionales. Puedes seleccionarlos manualmente.';return;}if(recommend){this.recommendation=data.draft.recomendados||[];this.recommendationNotes=data.draft.pendientes||[];this.success=this.recommendation.length?'Revisa la sugerencia y pulsa Usar esta selección de módulos.':'La IA no confirmó módulos para este producto. Revisa sus características.';return;}this.draft=applyProposalServices(data.draft,this.supportSelected,{annualFee:this.annualFee});this.success='Propuesta redactada. Revisa el borrador y pulsa Aplicar borrador a la proforma para incluirlo en el documento.';}catch(e){if(seq===this._sequence)this.error=e.name==='AbortError'?'La consulta tardó demasiado. Tus textos actuales se conservan.':e.message;}finally{clearTimeout(timer);if(seq===this._sequence){this.busy=false;this._abort=null;}}},

 async loadTemplate(){if(!this.settings || !this.active || this.value.tipo!=='sistemas')return;const id=Number(this.templateId)||Number((this.templateProducts[0]||{}).IdProducto);if(!id)return;this.templateId=id;const seq=(this._templateSequence||0)+1;this._templateSequence=seq;this.templateMessage='';try{const data=await this.call({mode:'proposal_template_get',id});if(seq!==this._templateSequence)return;this.templateLoaded=!!data.template;if(!data.template){this.supportSelected=defaultProposalServices();this.annualFee='';return;}const t=data.template;this.rubro=t.rubro||'';this.style=t.estilo||'corporativo';this.needs=t.necesidades||'';this.selected=(t.modulos||[]).filter(id=>this.modules.some(m=>m.id===id));this.annualFee=t.anualidad_facturacion||'';this.supportSelected=Array.isArray(t.soportes)?t.soportes.filter(id=>this.supportOptions.some(s=>s.id===id)):defaultProposalServices();const next=Object.assign({},this.value);let applied=false;for(const k of ['alcance','entregables','condiciones'])if(!String(next[k]||'').trim()){next[k]=(t.actual||{})[k]||'';applied=true;}if(applied)this.$emit('input',next);this.templateMessage='Configuración recuperada. Los textos que ya escribiste se conservan.';}catch(e){this.templateMessage=e.message;}},
 async saveTemplate(){if(!this.templateId||this.disabled||this.busy)return;if(!this.servicesReady()){this.templateMessage=this.error;return;}if(!['alcance','entregables','condiciones'].every(k=>String(this.value[k]||'').trim())){this.templateMessage='Completa y revisa los tres apartados antes de guardar.';return;}const finalTexts=applyProposalServices(this.value,this.supportSelected,{annualFee:this.annualFee});if(['alcance','entregables','condiciones'].some(k=>finalTexts[k].length>12000)){this.templateMessage='Resume los textos antes de guardar: superan el espacio disponible.';return;}this.savingTemplate=true;try{await this.call({mode:'proposal_template_save',id:Number(this.templateId),rubro:this.rubro||'Servicios empresariales',estilo:this.style,necesidades:this.needs,modulos:this.selected,soportes:this.supportSelected,anualidad_facturacion:this.supportSelected.includes('annual_billing')?Number(this.annualFee):null,actual:{alcance:finalTexts.alcance,entregables:finalTexts.entregables,condiciones:finalTexts.condiciones},productos:[]});this.$emit('input',finalTexts);this.templateLoaded=true;this.templateMessage='Plantilla guardada para este producto. Se cargará en las siguientes proformas; los cambios de una proforma no modifican la plantilla hasta volver a guardarla.';}catch(e){this.templateMessage=e.message;}finally{this.savingTemplate=false;}},
 guidedDraft(){if(!this.servicesReady())return;if(!this.rubro.trim())this.rubro='Servicios empresariales';const names=this.modules.filter(m=>this.selected.includes(m.id)).map(m=>m.name);const products=this.templateProducts.map(p=>p.Producto).filter(Boolean);this.draft={alcance:this.value.alcance||'Propuesta de sistemas de '+this.rubro+'.\n\nSolución: '+(products.join('; ')||'sistema de gestión empresarial')+'.\n\nObjetivo: centralizar la información y facilitar el seguimiento de las operaciones incluidas, con una configuración ajustada a los procesos acordados con el cliente.'+(this.needs?'\n\nNecesidades del cliente: '+this.needs:''),entregables:this.value.entregables||'Plan de implementación propuesto, sujeto a validación: \n1. Revisión de los procesos y datos necesarios para la configuración.\n2. Configuración de los módulos incluidos y validación conjunta de los flujos acordados.\n3. Coordinación de la orientación a usuarios y puesta en marcha.\n\nConfirmar responsables, plazo, capacitación y documentación antes de aprobar la oferta.',condiciones:this.value.condiciones||'La propuesta comprende exclusivamente los productos y módulos detallados. Confirmar por escrito la vigencia de licencia, usuarios, locales, soporte, renovaciones y forma de pago. Los servicios adicionales requieren una evaluación y cotización independiente.\n\nPara continuar, revisemos juntos el alcance y coordinemos los siguientes pasos de implementación.',pendientes:['Confirmar usuarios, locales y plazo de implementación.','Precisar licencia, soporte y renovación aplicables a este producto.']};this.draft=applyProposalServices(this.draft,this.supportSelected,{annualFee:this.annualFee});this.reviewed=false;this.applyMode='empty';this.error='';this.success='Base guiada preparada sin consultar IA. Revisa y aplica; para una redacción personalizada usa Mejorar presentación con IA.';},
 cancelRequest(){this._sequence=(this._sequence||0)+1;if(this._abort)this._abort.abort();this._abort=null;this.busy=false;},
 applyServices(){if(this.disabled||this.busy||!this.servicesReady())return;const next=applyProposalServices(this.value,this.supportSelected,{annualFee:this.annualFee});if(['alcance','entregables','condiciones'].some(k=>next[k].length>12000)){this.error='Los textos superan el espacio disponible. Resume el contenido antes de aplicar los servicios.';return;}this.$emit('input',next);this.success='Servicios aplicados al alcance, la implementación y las condiciones. Guarda la configuración para reutilizarlos con este producto.';},
 applyDraft(){if(!this.reviewed || !this.draft || this.disabled || !this.servicesReady())return;const next=Object.assign({},this.value);let count=0;for(const key of ['alcance','entregables','condiciones'])if(this.applyMode==='replace' || !String(next[key]||'').trim()){next[key]=applyProposalServices(this.draft,this.supportSelected,{annualFee:this.annualFee})[key];if(key==='alcance'){const names=this.modules.filter(m=>this.selected.includes(m.id)).map(m=>m.name);if(names.length && !next[key].includes('Módulos incluidos:'))next[key]+='\n\nMódulos incluidos: '+names.join('; ')+'.';next[key]=next[key].slice(0,12000);}count++;}this.$emit('input',next);this.success=count?'Borrador aplicado. Revisa los textos finales antes de crear o guardar la proforma.':'Tus campos ya tienen contenido. Elige reemplazar textos si deseas aplicar este borrador.';},
 stopVoice(){const recognition=this._recognition;this._recognition=null;if(recognition){recognition.onresult=null;recognition.onerror=null;recognition.onend=null;try{recognition.abort();}catch(e){}}this.dictating='';this.interim='';},
 dictate(field){if(this.dictating===field){this.stopVoice();return;}this.stopVoice();if(!this.voiceSupported || this.disabled || this.busy)return;this.voiceError='';const Speech=window.SpeechRecognition || window.webkitSpeechRecognition;const recognition=new Speech();this._recognition=recognition;recognition.lang='es-PE';recognition.continuous=false;recognition.interimResults=true;this.dictating=field;recognition.onresult=event=>{if(this._recognition!==recognition)return;let finalText='',interim='';for(let i=event.resultIndex;i<event.results.length;i++){if(event.results[i].isFinal)finalText+=event.results[i][0].transcript+' ';else interim+=event.results[i][0].transcript;}this.interim=interim;if(finalText.trim()){if(field==='needs')this.needs=(this.needs+' '+finalText.trim()).trim().slice(0,4000);else this.set(field,((this.value[field]||'')+' '+finalText.trim()).trim().slice(0,12000));}};recognition.onerror=event=>{this.voiceError=event.error==='not-allowed'?'Permite el micrófono para dictar. También puedes escribir.':'No se pudo completar el dictado. Tus textos se conservan.';this.stopVoice();};recognition.onend=()=>{if(this._recognition===recognition){this._recognition=null;this.dictating='';this.interim='';}};try{recognition.start();}catch(e){this.voiceError='No se pudo iniciar el micrófono.';this.stopVoice();}}
 }
};
